const date = new Date($input.first().json.timestamp);

const day = date.getDate(); // no leading zero
const month = date.getMonth() + 1; // JS months are 0-based
const year = date.getFullYear().toString().slice(-2); // '25' from '2025'

const formattedDate = `${day}/${month}/${year}`;
const yesterday = `${day-1}/${month}/${year}`;

return [{
  json: {
    todayDate: formattedDate,
    yesterday
  }
}];

// --- Utility: Clean monetary strings or fallback to 0
const cleanKsh = (val) => {
  if (typeof val === "number") return val;
  if (!val || typeof val !== "string") return 0;
  return parseFloat(val.replace(/Ksh/i, "").replace(/,/g, "").trim()) || 0;
};

// --- Normalization map for field names with known typos and variations
const keyMap = {
  "transaction id": "TransactionID",
  "transactionid": "TransactionID",
  "amount": "Amount",
  "ammount": "Amount",
  "sender": "Sender",
  "recipient": "Recipient",
  "date": "Date",
  "time": "Time",
  "balance": "Balance",
  "transaction cost": "TransactionCost",
  "transactin cost": "TransactionCost"
};

const results = [];
const seenTransactionIDs = new Set();

for (const item of items) {
  let text;
  try {
    text = item.json?.candidates?.[0]?.content?.parts?.[0]?.text;
    if (!text) continue; // Skip blank item

    // Remove ```json and ``` markers
    const jsonBlock = text.replace(/```json|```/gi, "").trim();

    let data;
    try {
      // Try JSON.parse
      data = JSON.parse(jsonBlock);
    } catch {
      // Fallback: manual line parsing
      data = {};
      const lines = jsonBlock.split("\n");
      for (const line of lines) {
        const [rawKey, ...rest] = line.split(":");
        if (!rawKey || rest.length === 0) continue;
        const normalizedKey = keyMap[rawKey.trim().toLowerCase()];
        if (normalizedKey) {
          data[normalizedKey] = rest.join(":").trim().replace(/^"|"$/g, "");
        }
      }
    }

    const transactionID = data.TransactionID?.trim();
    if (!transactionID) continue; // Skip if no Transaction ID
    if (seenTransactionIDs.has(transactionID)) continue; // Skip duplicates
    seenTransactionIDs.add(transactionID);

    const amount = cleanKsh(data.Amount);
    const sender = data.Sender || "NIL";
    const recipient = data.Recipient || "NIL";
    const dateStr = data.Date || "01/01/25";
    const timeStr = data.Time || "12:00 AM";
    const balance = cleanKsh(data.Balance);
    const transactionCost = cleanKsh(data.TransactionCost);

    // Parse date + time into ISO timestamp
    let timestamp = new Date().toISOString(); // fallback
    try {
      const [day, month, year] = dateStr.split("/").map(Number);
      const isoDate = `${2000 + year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
      const fullDateStr = `${isoDate} ${timeStr} GMT+3`;
      const parsedDate = new Date(fullDateStr);
      if (!isNaN(parsedDate.getTime())) {
        timestamp = parsedDate.toISOString();
      }
    } catch {
      // fallback remains
    }

    results.push({
      json: {
        TransactionID: transactionID,
        Amount: amount,
        Sender: sender,
        Recipient: recipient,
        Date: dateStr,
        Time: timeStr,
        Timestamp: timestamp,
        Balance: balance,
        TransactionCost: transactionCost
      }
    });

  } catch (err) {
    continue; // Silent skip on error
  }
}

// ✅ Sort results chronologically
results.sort((a, b) => new Date(a.json.Timestamp) - new Date(b.json.Timestamp));

return results;
